import { defineEnableDraftMode } from "next-sanity/draft-mode";
import { getClient } from "@/app/sanity-api/sanity.client";

// Draft mode is only enabled with a valid secret generated by the Studio's
// Presentation tool (i.e. for users logged into the Studio); otherwise 401.
const { GET: enableDraftMode } = defineEnableDraftMode({
  client: getClient().withConfig({ token: process.env.SANITY_API_READ_TOKEN }),
});

export async function GET(request: Request) {
  // Open-redirect guard: the target must be an internal path ("/..."),
  // never "//host", "/\host" or an absolute URL.
  const pathname = new URL(request.url).searchParams.get(
    "sanity-preview-pathname",
  );
  if (pathname !== null && !/^\/(?![/\\])/.test(pathname)) {
    return new Response("Invalid redirect", { status: 400 });
  }
  return enableDraftMode(request);
}
